<details open class="ytg ytg-top"><summary class="ytg-summary"><span class="ytg-summary-label">本回 · 场记</span><span class="ytg-summary-sub">SCENE</span></summary><div class="ytg-content"><div class="ytg-scene"><div class="ytg-title">$1</div><div class="ytg-time">$2</div><div class="ytg-place">$3</div><div class="ytg-cast"><span class="ytg-cast-label">在场</span><span class="ytg-cast-names">$4</span></div></div></div></details>
<script>
(function() {
  try {
    const pDoc = window.parent && window.parent.document;
    if (pDoc) {
      const pRoot = pDoc.documentElement;
      const pBody = pDoc.body;
      const csRoot = window.parent.getComputedStyle(pRoot);
      const mesEl = pDoc.querySelector('.mes_text') || pBody;
      const csMes = window.parent.getComputedStyle(mesEl);
      const vars = ['--SmartThemeBodyColor', '--SmartThemeQuoteColor', '--SmartThemeEmColor', '--SmartThemeBlurTintColor', '--SmartThemeBorderColor'];
      vars.forEach(v => {
        const val = csRoot.getPropertyValue(v) || csMes.getPropertyValue(v);
        if (val) document.documentElement.style.setProperty(v, val.trim());
      });
      document.body.style.fontFamily = csMes.fontFamily;
      document.body.style.fontSize = csMes.fontSize;
      document.body.style.color = csMes.color;
    }
  } catch (e) {}
  function syncFrameHeight() {
    try {
      const fe = window.frameElement;
      if (!fe) return;
      const h = Math.max(document.documentElement.scrollHeight, document.body.scrollHeight);
      if (h > 0) {
        fe.style.setProperty('height', (h + 4) + 'px', 'important');
        fe.style.setProperty('max-height', 'none', 'important');
      }
    } catch (e) {}
  }
  document.querySelectorAll('details').forEach(d => d.addEventListener('toggle', () => {
    syncFrameHeight();
    setTimeout(syncFrameHeight, 60);
  }));
  if (typeof ResizeObserver !== 'undefined') {
    new ResizeObserver(syncFrameHeight).observe(document.body);
  }
  window.addEventListener('load', syncFrameHeight);
  setTimeout(syncFrameHeight, 30);
})();
</script>
